        // Inner cavity (open at bottom, closed at top)
        translate([0,0,0])
            cylinder(h=depth, r=id/2);

        // Slight lead-in chamfer inside at opening
        translate([0,0,0])
            cylinder(h=chamfer+0.2, r1=(id/2)+chamfer, r2=id/2);
