    rim_r = 4.5;
    rim_t = 0.6;
    translate([0,0,plate_t - rim_t])
        linear_extrude(height=rim_t)
            difference(){
                rounded_rect_2d(rim_w, rim_h, rim_r);
                rounded_rect_2d(rim_w-2.2, rim_h-2.2, rim_r-1.1);
            }
}
