    r2 = min(r, min(L,H)/2);
    hull(){
        translate([r2, r2]) circle(r=r2);
        translate([L-r2, r2]) circle(r=r2);
        translate([r2, H-r2]) circle(r=r2);
        translate([L-r2, H-r2]) circle(r=r2);
    }
