module teeth_cutout_2d(){
    // Create a sawtooth cutout along the bottom edge by subtracting triangles
    n = floor(blade_len/tooth_pitch);
    for(i=[0:n-1]){
        x0 = i*tooth_pitch;
        translate([x0, 0])
            tooth_profile_2d(tooth_pitch, tooth_height, tooth_tip_flat);
    }
