module bimetal_3d(){
    // Slightly proud strip (very small thickness difference)
    strip_th = blade_thickness*0.15;
    translate([0,0,blade_thickness/2 - strip_th/2])
        linear_extrude(height=strip_th, center=true, convexity=5)
            intersection(){
