    base_color = [0.06, 0.06, 0.07];
    weave_color = [0.12, 0.12, 0.13];

    // Base tube
    color(base_color)
        tube(od, id, h);

    // Subtle weave emboss on outer surface
    color(weave_color)
        carbon_weave_shell(od, h, weave_pitch, weave_depth, weave_angle);
}

