                cylinder(h = chamfer, r = chamfer, center = false);
            }
        } else {
            cylinder(h = L, r = r_out, center = false);
        }

        // Inner bore (extend slightly to ensure clean subtraction)
        translate([0,0,-0.5])
            cylinder(h = L + 1.0, r = r_in, center = false);
    }
}

